            for i in range(sheet.max_row,1,-1):
                row=[sheet.cell(i,j).value for j in range(1,min(sheet.max_column,2)+1)]
                if not row_country(row,keys): sheet.delete_rows(i,1)
        elif title==norm('Datos Completos'):
            for i in range(sheet.max_row,1,-1):
                file_value=norm(sheet.cell(i,1).value)
